head.script:
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue + "\n");
};



// 마우스가 Header 경계 위를 지날 때, 리사이즈 커서가 나타난 오프셋을 기록한다.
//  오프셋 0 = 경계선 위, 음수 = 경계선 왼쪽, 양수 = 경계선 오른쪽.
scwin.gVar = { hit : { hcol1 : [], hcol2 : [] } };

scwin.currentCursor = function (objEl) {
    var objNode = objEl;
    while (objNode !== null && objNode !== document.body) {
        if (objNode.style && objNode.style.cursor) return objNode.style.cursor;
        objNode = objNode.parentElement;
    }
    return document.body.style.cursor || "";
};

scwin.onMove = function (objEvent) {
    var arrId = ["hcol1", "hcol2"];
    for (var i = 0; i < arrId.length; i++) {
        var objTh = document.querySelector("th[id$='" + arrId[i] + "']");
        if (objTh === null) continue;

        var objRect = objTh.getBoundingClientRect();
        if (objEvent.clientY < objRect.top || objEvent.clientY > objRect.bottom) continue;

        var nOffset = Math.round(objEvent.clientX - objRect.right);
        if (nOffset < -20 || nOffset > 20) continue;

        if (scwin.currentCursor(objEvent.target) === "col-resize") {
            var arrHit = scwin.gVar.hit[arrId[i]];
            if (arrHit.indexOf(nOffset) === -1) arrHit.push(nOffset);
        }
    }
};

scwin.onpageload = function () {
    document.addEventListener("mousemove", scwin.onMove, true);
};



// 기록된 감지 영역을 출력한다.
scwin.btn_measure_onclick = function (e) {
    var fnText = function (arrHit) {
        if (arrHit.length === 0) return "기록 없음 (경계 위를 지나가지 않았거나 감지되지 않음)";
        arrHit.sort(function (a, b) { return a - b; });
        return "오프셋 " + arrHit[0] + " ~ " + arrHit[arrHit.length - 1] + " / 폭 " + arrHit.length + "px";
    };

    scwin.setReturnValue("=====리사이즈 감지 영역 (실측)=====");
    scwin.setReturnValue("col1 오른쪽 경계 (오른쪽이 일반 Column) : " + fnText(scwin.gVar.hit.hcol1));
    scwin.setReturnValue("col2 오른쪽 경계 (오른쪽이 fixColumnWidth=true) : " + fnText(scwin.gVar.hit.hcol2));
    scwin.setReturnValue("");
};



scwin.btn_reset_onclick = function (e) {
    scwin.gVar.hit = { hcol1 : [], hcol2 : [] };
    scwin.setReturnValue("기록을 초기화했습니다. 두 경계 위를 다시 천천히 지나가십시오.");
    scwin.setReturnValue("");
};



// Drag 전후 너비 비교용
scwin.btn_checkWidth_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");
    scwin.setReturnValue("=====현재 컬럼 너비=====");
    scwin.setReturnValue("col1 (minWidth=120 / 초기 180) : " + objGrid.getColumnWidth(2) + "px");
    scwin.setReturnValue("col2 (minWidth=150 / 초기 200) : " + objGrid.getColumnWidth(3) + "px");
    scwin.setReturnValue("col3 (fixColumnWidth=true / 초기 120) : " + objGrid.getColumnWidth(4) + "px");
    scwin.setReturnValue("");
};
